-- c010-v002: Dan–menjawab Sekhanya anak Yehiel dari–keturunan [kere] Elam dan–berkata kepada–Ezra Kami telah–berdosa terhadap–Allah–kami dan–kami–menikahi perempuan asing dari–bangsa–bangsa negeri dan–sekarang ada harapan bagi–Israel mengenai ini
-- c010-v003: Dan–sekarang marilah–kita–membuat perjanjian dengan–Allah–kami untuk–mengusir semua perempuan dan–yang–dilahirkan dari–mereka menurut–nasihat Tuhan dan–yang–gemetar pada–perintah Allah–kami dan–menurut–Taurat biarlah–dilakukan
-- c010-v004: Bangkitlah karena atasmu urusan dan–kami bersamamu kuatkanlah dan–lakukanlah [paragraph]
-- c010-v005: Dan–bangkitlah Ezra dan–menyumpahi [obj] pembesar–pembesar para–imam orang–orang–Lewi dan–seluruh Israel untuk–melakukan sesuai–perkataan ini dan–mereka–bersumpah
-- c010-v006: Dan–bangkitlah Ezra dari–depan rumah Allah dan–pergi ke bilik Yohanan anak Elyasib dan–pergi ke–sana roti tidak dia–makan dan–air tidak dia–minum karena dia–berkabung atas pelanggaran para–buangan [section]
-- c010-v007: Dan–mereka–mengumumkan suara di–Yehuda dan–Yerusalem kepada–semua anak–anak pembuangan untuk–berkumpul Yerusalem
-- c010-v008: Dan–setiap yang tidak datang dalam–tiga hari menurut–nasihat para–pembesar dan–para–tua–tua biarlah–ditumpas semua hartanya dan–dia akan–dipisahkan dari–jemaah pembuangan [section]
-- c010-v009: Dan–berkumpul semua orang–orang Yehuda dan–Benyamin Yerusalem dalam–tiga hari itu bulan kesembilan pada–tanggal–dua–puluh bulan dan–duduk semua rakyat di–lapangan rumah Allah menggigil karena perkara dan–karena–hujan [paragraph]
-- c010-v010: Dan–bangkitlah Ezra imam dan–berkata kepada–mereka Kamu telah–berdosa dan–kamu–menikahi perempuan asing untuk–menambah atas kesalahan Israel
-- c010-v011: Dan–sekarang berikanlah pengakuan kepada–TUHAN Allah nenek–moyang–kamu dan–lakukanlah kehendak–Nya dan–pisahkanlah–diri–kamu dari–bangsa–bangsa negeri dan–dari perempuan asing
-- c010-v012: Dan–menjawab seluruh jemaah dan–berkata suara keras demikianlah [kere] sesuai–perkataanmu atas–kami untuk–dilakukan
-- c010-v013: Tetapi rakyat banyak dan–waktu hujan dan–tidak ada–kekuatan untuk–berdiri di–luar dan–pekerjaan bukan untuk–satu–hari satu dan–tidak untuk–dua karena kami–memperbanyak untuk–melanggar dalam–perkara ini
-- c010-v014: Biarlah–berdiri kiranya pembesar–pembesar–kami untuk–seluruh jemaah dan–setiap yang di–kota–kota–kami yang–menikahi perempuan asing biarlah–datang pada–waktu yang–ditetapkan dan–bersama–mereka tua–tua kota demi–kota dan–hakim–hakimnya sampai memalingkan murka kemarahan Allah–kami dari–kami mengenai perkara ini [paragraph]
